<?php
declare(strict_types=1);
function serverEvent(array $e): array {$rsvps=listEntities('rsvp',$e['id']);$e['goingCount']=count(array_filter($rsvps,fn($r)=>$r['status']==='going'));$e['interestedCount']=count(array_filter($rsvps,fn($r)=>$r['status']==='interested'));$e['viewerStatus']=entity('rsvp-'.$e['id'].'-'.user()['id'])['status']??null;return $e;}
function communityRoutes(string $m,string $path,array $b): ?array {
 if(!preg_match('#^/api/groups/([^/]+)/(community|insights|events|boosts|subscription-tiers|subscriptions|automod-rules|channel-follows|transfer|members)(?:/(.*))?$#',$path,$a))return null;$gid=$a[1];$g=groupAccess($gid);$id=user()['id'];$sub=$a[2];$tail=$a[3]??'';
 if($sub==='community'&&$m==='GET'){
  $boosts=array_values(array_filter(listEntities('boost',$gid),fn($v)=>!$v['cancelledAt']&&$v['expiresAt']>now()));$subs=array_values(array_filter(listEntities('subscription',$gid),fn($v)=>$v['status']==='active'&&$v['currentPeriodEnd']>now()));$tiers=listEntities('tier',$gid);$revenue=0;foreach($subs as$s)$revenue+=(entity($s['tierId'],'tier')['priceMonthly']??0);
  return ['events'=>array_map('serverEvent',listEntities('server_event',$gid)),'boosts'=>['count'=>count($boosts),'level'=>count($boosts)>=14?3:(count($boosts)>=7?2:(count($boosts)>=2?1:0)),'viewerBoosting'=>in_array($id,array_column($boosts,'userId'),true),'supporters'=>array_map(fn($v)=>['userId'=>$v['userId'],'displayName'=>account($v['userId'])['displayName'],'expiresAt'=>$v['expiresAt']],$boosts)],'tiers'=>$tiers,'subscriptions'=>array_map(fn($s)=>$s+['tierName'=>entity($s['tierId'],'tier')['name']??''],array_values(array_filter($subs,fn($s)=>$s['userId']===$id))),'monetization'=>groupCan($gid,'viewCreatorMonetizationAnalytics')?['activeSubscriptions'=>count($subs),'monthlyRevenue'=>$revenue]:null];
 }
 if($sub==='insights'&&$m==='GET'){gp($gid,'viewServerInsights');$channels=listEntities('channel',$gid);$ids=array_column($channels,'id');$messages=array_values(array_filter(listEntities('message'),fn($v)=>in_array($v['channelId'],$ids,true)&&!$v['deleted']));$daily=[];for($n=29;$n>=0;$n--){$at=strtotime('-'.$n.' day 00:00 UTC')*1000;$daily[]=['at'=>$at,'messages'=>count(array_filter($messages,fn($v)=>$v['createdAt']>=$at&&$v['createdAt']<$at+86400000)),'members'=>count(array_filter(members($gid),fn($v)=>$v['joinedAt']>=$at&&$v['joinedAt']<$at+86400000))];}return ['insights'=>['members'=>count(memberIds($gid)),'channels'=>count($channels),'messages'=>count($messages),'activeMembers'=>count(array_unique(array_column(array_filter($messages,fn($v)=>$v['createdAt']>now()-604800000),'authorId'))),'series'=>$daily,'topChannels'=>array_map(fn($c)=>['id'=>$c['id'],'name'=>$c['name'],'messages'=>count(array_filter($messages,fn($v)=>$v['channelId']===$c['id']))],$channels)]];}
 if($sub==='events'){
  if($tail===''&&$m==='POST'){gp($gid,'createEvents');$name=required($b,'name',100);$starts=integerValue($b,'startsAt',now()-60000,PHP_INT_MAX);$channel=$b['channelId']??null;if($channel){$ch=canTarget('channels',$channel);if($ch['groupId']!==$gid)fail(400,'Invalid event channel.');cp($ch,'createEvents');}$e=putEntity('server_event',['groupId'=>$gid,'name'=>$name,'description'=>$b['description']??null,'startsAt'=>$starts,'endsAt'=>$b['endsAt']??null,'location'=>$b['location']??null,'channelId'=>$channel,'creatorId'=>$id,'status'=>'scheduled'],$gid,$id);emitGroup($gid,'server:event-created',['groupId'=>$gid,'event'=>serverEvent($e)]);http_response_code(201);return ['event'=>serverEvent($e)];}
  $parts=explode('/',$tail);$e=mustEntity($parts[0],'server_event');if($e['groupId']!==$gid)fail(404,'Event not found.');if(($parts[1]??'')==='rsvp'&&$m==='PUT'){$status=$b['status']??null;$rid='rsvp-'.$e['id'].'-'.$id;if($status===null)removeEntity($rid);else putEntity('rsvp',['id'=>$rid,'userId'=>$id,'status'=>enumValue($status,['going','interested'])],$e['id'],$id);return ['status'=>$status];}
  if(!groupCan($gid,'manageEvents')&&!($e['creatorId']===$id&&groupCan($gid,'createEvents')))fail(403,'Cannot manage this event.');if($m==='PATCH'){foreach(['name','description','startsAt','endsAt','location','status']as$k)if(array_key_exists($k,$b))$e[$k]=$b[$k];required($e,'name',100);integerValue($e,'startsAt',0,PHP_INT_MAX);if($e['endsAt']!==null&&$e['endsAt']<=$e['startsAt'])fail(400,'Invalid end time.');$e=putEntity('server_event',$e,$gid,$e['creatorId']);return ['event'=>serverEvent($e)];}if($m==='DELETE'){sql('DELETE FROM entities WHERE kind=? AND parent_id=?',['rsvp',$e['id']]);removeEntity($e['id']);emitGroup($gid,'server:event-deleted',['groupId'=>$gid,'eventId'=>$e['id']]);return ['ok'=>true];}
 }
 if($sub==='boosts'){
  if($tail===''&&$m==='POST'){return transaction(function()use($gid,$id){sql('SELECT id FROM accounts WHERE id=? FOR UPDATE',[$id]);foreach(listEntities('boost',null,$id)as$v)if(!$v['cancelledAt']&&$v['expiresAt']>now())fail(409,'You already have an active boost.');$boost=putEntity('boost',['groupId'=>$gid,'userId'=>$id,'startedAt'=>now(),'expiresAt'=>now()+2592000000,'cancelledAt'=>null],$gid,$id);http_response_code(201);return ['boost'=>$boost];});}
  if($tail==='mine'&&$m==='DELETE'){foreach(listEntities('boost',$gid,$id)as$v){$v['cancelledAt']=now();putEntity('boost',$v,$gid,$id);}return ['ok'=>true];}
 }
 if($sub==='subscription-tiers'&&$m==='POST'){gp($gid,'manageGroup');$name=required($b,'name',64,2);foreach(listEntities('tier',$gid)as$t)if(mb_strtolower($t['name'])===mb_strtolower($name))fail(409,'Duplicate tier.');http_response_code(201);return ['tier'=>putEntity('tier',['groupId'=>$gid,'name'=>$name,'description'=>$b['description']??null,'priceMonthly'=>integerValue($b,'priceMonthly',0,100000000,0),'benefits'=>stringList($b['benefits']??[],20,100),'active'=>true],$gid,$id)];}
 if($sub==='subscriptions'){
  if($tail===''&&$m==='POST'){$tier=mustEntity(required($b,'tierId',64),'tier');if($tier['groupId']!==$gid||!$tier['active'])fail(404,'Tier not found.');http_response_code(201);return ['subscription'=>putEntity('subscription',['tierId'=>$tier['id'],'groupId'=>$gid,'userId'=>$id,'status'=>'active','startedAt'=>now(),'currentPeriodEnd'=>now()+2592000000,'cancelledAt'=>null],$gid,$id)];}
  if($tail&&$m==='DELETE'){$s=mustEntity($tail,'subscription');if($s['groupId']!==$gid||$s['userId']!==$id)fail(404,'Subscription not found.');$s['status']='cancelled';$s['cancelledAt']=now();putEntity('subscription',$s,$gid,$id);return ['ok'=>true];}
 }
 if($sub==='automod-rules'){
  gp($gid,'manageGroup');if($tail===''&&$m==='POST'){$rule=putEntity('automod',['groupId'=>$gid,'name'=>required($b,'name',100),'triggerType'=>enumValue($b['triggerType']??null,['keyword','spam','mention_spam']),'action'=>enumValue($b['action']??'block',['block','alert','timeout']),'enabled'=>(bool)($b['enabled']??true),'config'=>$b['config']??[]],$gid,$id);return ['rule'=>$rule];}if($tail&&$m==='DELETE'){$r=mustEntity($tail,'automod');if($r['groupId']!==$gid)fail(404,'Rule not found.');removeEntity($tail);return ['ok'=>true];}
 }
 if($sub==='channel-follows'){
  gp($gid,'manageChannels');if($m==='GET')return ['follows'=>array_map(fn($f)=>$f+['sourceChannelName'=>entity($f['sourceChannelId'],'channel')['name']??'','targetChannelName'=>entity($f['targetChannelId'],'channel')['name']??''],listEntities('follow',$gid))];
  if($m==='POST'){$src=canTarget('channels',required($b,'sourceChannelId',64));$target=canTarget('channels',required($b,'targetChannelId',64));if($src['type']!=='announcement'||$target['groupId']!==$gid||$src['id']===$target['id'])fail(400,'Invalid announcement follow.');return ['follow'=>putEntity('follow',['id'=>'follow-'.hash('sha256',$src['id'].':'.$target['id']),'groupId'=>$gid,'sourceChannelId'=>$src['id'],'targetChannelId'=>$target['id']],$gid,$id)];}
  if($m==='DELETE'&&preg_match('#^([^/]+)/([^/]+)$#',$tail,$p)){removeEntity('follow-'.hash('sha256',$p[1].':'.$p[2]));return ['ok'=>true];}
 }
 if($sub==='transfer'&&$m==='POST'){
  if($g['ownerId']!==$id&&!capability('admin'))fail(403,'Only owner may transfer.');$uid=required($b,'userId',64);$seat=member($gid,$uid)??fail(400,'New owner must be a member.');$old=member($gid,$g['ownerId']);$old['memberRole']='admin';$seat['memberRole']='owner';transaction(function()use($gid,$g,$uid,$old,$seat){addMember($gid,$g['ownerId'],$old);addMember($gid,$uid,$seat);$g['ownerId']=$uid;putEntity('group',$g,'',$uid);});return ['group'=>groupView(mustEntity($gid,'group'))];
 }
 if($sub==='members'&&$tail===''&&$m==='GET')return ['members'=>members($gid)];
 return null;
}
